function bind(){var f=document.getElementById('saudiFilter');if(f)f.oninput=function(){var q=f.value.toLowerCase();document.querySelectorAll('.saudi-card').forEach(function(e){e.style.display=e.textContent.toLowerCase().indexOf(q)>=0?'':'none'})};document.querySelectorAll('.saudi-watch').forEach(function(b){b.onclick=function(){var c=candidates[+b.dataset.i];var m=document.getElementById('saudi-msg-'+b.dataset.i);m.textContent='⭐ '+c.name+' takip için seçildi.';b.textContent='✓ Takipte'}});document.querySelectorAll('.saudi-hunter').forEach(function(b){b.onclick=function(){var c=candidates[+b.dataset.i];document.getElementById('saudi-msg-'+b.dataset.i).textContent='Hunter ile e-posta aranacak: '+c.name}});var all=document.getElementById('saudiMailAll');if(all)all.onclick=function(){var e=candidates.filter(function(c){return c.email}).map(function(c){return c.email}).join(',');if(e)location.href=mail({email:e})}}
